  function getMessages(){ var m = load(K.messages, null); if(!m) m = JSON.parse(JSON.stringify(DEFAULT_MESSAGES)); return m; }
  function getApproval(){ var a = load(K.approval, null); if(!a) a = JSON.parse(JSON.stringify(DEFAULT_APPROVAL)); return a; }
  // 审批级别：0=免审批直接下单；1=一级审批；2=一级+二级加签（超 50000）
  function approvalNeeded(amount){
    var a = getApproval();
    if(amount <= a.threshold) return 0;
    if(amount > 50000) return 2;
    return 1;
  }
  function approvalDesc(level){
    var a = getApproval();
    if(level===0) return '金额未超阈值 ¥'+a.threshold+'，免审批，可直接采购下单';
    if(level===2) return '金额超 ¥50000，需 '+a.approver1+' 审批并由 '+a.approver2+' 加签';
    return '金额超阈值 ¥'+a.threshold+'，需 '+a.approver1+' 审批后采购下单';
  }
  function setOrders(v){ save(K.orders, v); }
  function setMessages(v){ save(K.messages, v); }
  function unreadCount(){ return getMessages().filter(function(m){ return m.unread; }).length; }

  /* ================= 规则引擎（确定性计算） ================= */
  function payDays(t){ if(t==='现款') return 0; var n=parseInt(t,10); return isNaN(n)?0:n; }
  function taxInc(q){ return q.tax_included ? q.price : q.price*(1+q.tax_rate); }
  function deliv(q){ return taxInc(q) + q.freight; }
  function eff(q, c){ c = c || getCfg(); return deliv(q) / (1 + c.fundRate*payDays(q.payment_terms)/365); }
  function quotesFor(sku){ return quotes.filter(function(q){ return q.sku_code===sku; }); }
  function dealsFor(sku){ return deals.filter(function(d){ return d.sku_code===sku; }); }
  function snapsFor(sku){ return snapshots.filter(function(s){ return s.sku_code===sku; }); }
  // 采购量（默认取报价场景量，可在详情页覆盖；影响 MOQ 满足度打分）
