  function pickChannel(cid){ selChannel = (selChannel===cid ? null : cid); pages.channels(); }

  /* ---- 供应商绩效 ---- */
  function perfRows(){
    var byId={}; suppliers.forEach(function(s){ byId[s.supplier_id]={ n:0, leadSum:0, win:0 }; });
    var minEff={}; products.forEach(function(p){ minEff[p.sku_code]=Infinity; });
    var c=getCfg();
    quotes.forEach(function(q){ var e=eff(q,c); if(e<minEff[q.sku_code]) minEff[q.sku_code]=e; });
    quotes.forEach(function(q){ var m=byId[q.supplier_id]; m.n++; m.leadSum+=q.lead_time_days; if(eff(q,c)===round2(minEff[q.sku_code])) m.win++; });
    return suppliers.map(function(s){
      var m=byId[s.supplier_id];
      var base = s.rating==='A'?85:(s.rating==='B'?70:55);
      var qual = s.is_qualified?10:0;
      var leadAvg = m.n? m.leadSum/m.n : null;
      var pen = (leadAvg==null||leadAvg<=3)?0:Math.round((leadAvg-3)*1.2);
      var winB = m.n? Math.round(m.win/m.n*5):0;
      var score = Math.max(0, Math.min(100, base+qual+winB-pen));
      var lbl = score>=85?'优':(score>=70?'良':'一般');
      var cls = score>=85?'rating-A':(score>=70?'rating-B':'rating-C');
      return { s:s, n:m.n, leadAvg:leadAvg, win:m.win, score:score, lbl:lbl, cls:cls };
    });
  }
