  function orderDraft(){
    var c = buildComparison(detailSku); var r = c.rows[picked]||c.rows[0]; var p = c.prod;
    var amt = round2(r.deliv*c.qty);
    var lvl = approvalNeeded(amt);
    var mall = mallOf(r.s);
    var id = 'PO-2026-' + (1000+getOrders().length) + getOrders().length;
    var mallHint = '生成后 PO 状态为「待处理」。点击「采购下单」即在「'+esc(mall)+'」生成<b>待支付订单</b>并获取商城单号（状态转「待支付」），随后「去支付」跳转商城完成支付。';
    showModal(
      '<h3>生成前置采购订单（PO）</h3>'+
      '<div class="kv"><span class="k">供应商</span><span>'+esc(r.s.name)+'</span>'+
      '<span class="k">商品</span><span>'+esc(p.name)+'（'+esc(p.sku_code)+'）</span>'+
      '<span class="k">数量</span><span>'+c.qty+' '+esc(p.unit)+'</span>'+
      '<span class="k">含税到厂单价</span><span>'+money(r.deliv)+' / '+esc(p.unit)+'</span>'+
      '<span class="k">有效到厂价</span><span>'+money(r.eff)+' / '+esc(p.unit)+'</span>'+
      '<span class="k">采购金额</span><span><b style="color:var(--brand)">'+money(amt)+'</b></span>'+
      '<span class="k">账期 / 交期</span><span>'+esc(r.q.payment_terms)+' / '+r.q.lead_time_days+' 天</span>'+
      '<span class="k">报价有效期</span><span>'+esc(r.q.valid_until)+'</span></div>'+
      '<div class="risk-box" style="margin-top:12px"><div class="t">⇄ 采购下单：在「'+esc(mall)+'」生成待支付订单</div>'+mallHint+'</div>'+
      (lvl>0
        ? '<div class="risk-box" style="margin-top:12px"><div class="t">⚠ 触发审批流</div>'+esc(approvalDesc(lvl))+'。生成后 PO 状态为「待审批」，审批通过后转为「待处理」。</div>'
        : '<div style="font-size:12px;color:var(--ink-3);margin-top:12px">'+esc(approvalDesc(lvl))+'。</div>')+
      '<div class="foot"><button class="btn" onclick="MPJ.closeModal()">取消</button><button class="btn primary" onclick="MPJ.confirmOrder(\''+id+'\')">确认生成</button></div>'
    );
  }
  function confirmOrder(id){
    var c=buildComparison(detailSku); var r=c.rows[picked]||c.rows[0]; var p=c.prod;
    var amt = round2(r.deliv*c.qty);
    var lvl = approvalNeeded(amt);
    var status = lvl>0 ? '待审批' : '待处理';
    var line = { sku_code:p.sku_code, name:p.name, supplier_id:r.s.supplier_id, supplier:r.s.name, channel_id:r.s.channel_id, qty:c.qty, unit:p.unit, price:r.deliv, eff_price:r.eff, pay:r.q.payment_terms, line_amount:amt };
    var orders=getOrders();
    orders.unshift({ id:id, code:p.sku_code, name:p.name, supplier:r.s.name, supplier_id:r.s.supplier_id, channel_id:r.s.channel_id, qty:c.qty, unit:p.unit, price:r.deliv, pay:r.q.payment_terms, status:status, date:'2026-10-31', approval:lvl, amount:amt, mall_type:mallTypeOf(r.s), mall_order_id:null, lines:[line] });
    setOrders(orders);
    var messages = getMessages();
    if(lvl>0){
      messages.unshift({ id:Date.now(), type:'订单', title:'采购订单 '+id+' 待审批', body:approvalDesc(lvl)+'。采购金额 '+money(amt)+'，请审批人及时处理。', time:'刚刚', unread:true });
    } else {
      messages.unshift({ id:Date.now(), type:'订单', title:'采购订单 '+id+' 已生成', body:'采购金额 '+money(amt)+'，未超审批阈值，PO 为「待处理」状态，可采购下单。', time:'刚刚', unread:true });
    }
    setMessages(messages);
    closeModal();
    showToast(lvl>0 ? ('PO '+id+' 已生成，进入审批流') : ('PO '+id+' 已生成'));
    location.href='purchase-orders.html';
  }
  function exportReport(){ showToast('已导出比价报告（mock）。真实环境输出 Excel / PDF 留档。'); }
  function applyQty(){
    var inp = el('qty-input'); if(!inp) return;
    var n = parseInt(inp.value, 10);
    if(isNaN(n) || n<=0){ showToast('请输入大于 0 的采购量'); return; }
    setQty(detailSku, n);
    renderDetail();
    showToast('采购量已更新为 '+n+'，比价已重算');
  }

